INSERT [dbo].[Recipes] ([Id], [Name], [Description], [TotalCost], [AuthorUserName], [CookingTime], [CreatedAt], [ImageUrl], [Instructions], [PreparationTime], [Servings], [TotalTime], [UpdatedAt]) VALUES (1, N'Curry z ciecierzyca i warzywami', N'1. Podsmaż cebule i czosnek na oleju rzepakowym. 2. Dodaj pokrojone ziemniaki i marchew, smaż przez kilka minut. 3. Dodaj ciecierzyce i pomidory w puszce. 4. Dopraw curry, tymiankiem, solą i pieprzem. 5. Duś na malym ogniu, az warzywa beda miekkie. 6. Podawaj na ciepło z ryżem lub chlebem naan.', CAST(9.06 AS Decimal(18, 2)), N'Richy', CAST(N'00:00:30' AS Time), CAST(N'0001-01-01T00:00:00.0000000' AS DateTime2), NULL, N'1.Kup produkty. 2.Przy tuj potrawe.', CAST(N'00:00:15' AS Time), 2, CAST(N'00:00:45' AS Time), NULL)
 
INSERT [dbo].[Recipes] ([Id], [Name], [Description], [TotalCost], [AuthorUserName], [CookingTime], [CreatedAt], [ImageUrl], [Instructions], [PreparationTime], [Servings], [TotalTime], [UpdatedAt]) VALUES (2, N'Pieczony kurczak z warzywami', N'1. Natrzyj kurczaka solą, pieprzem i rozmarynem. 2. Ułóż pokrojone ziemniaki, marchew, cebule i czosnek w naczyniu zaroodpornym. 3. Skrop olejem rzepakowym i piecz w 180°C przez 45 minut.', CAST(26.02 AS Decimal(18, 2)), N'Richy', CAST(N'00:00:30' AS Time), CAST(N'0001-01-01T00:00:00.0000000' AS DateTime2), NULL, N'1.Kup produkty. 2.Przy tuj potrawe.', CAST(N'00:00:15' AS Time), 2, CAST(N'00:00:45' AS Time), NULL)
 
INSERT [dbo].[Recipes] ([Id], [Name], [Description], [TotalCost], [AuthorUserName], [CookingTime], [CreatedAt], [ImageUrl], [Instructions], [PreparationTime], [Servings], [TotalTime], [UpdatedAt]) VALUES (3, N'Makaron z brokułami i sosem śmietanowym', N'1. Ugotuj makaron wedlug instrukcji na opakowaniu. 2. Ugotuj brokul na póltwardo. 3. Przy tuj sos ze smietany i parmezanu, dopraw solą i pieprzem. 4. Wymieszaj makaron z sosem i brokułem, podawaj na ciepło.', CAST(11.31 AS Decimal(18, 2)), N'Richy', CAST(N'00:00:30' AS Time), CAST(N'0001-01-01T00:00:00.0000000' AS DateTime2), NULL, N'1.Kup produkty. 2.Przy tuj potrawe.', CAST(N'00:00:15' AS Time), 2, CAST(N'00:00:45' AS Time), NULL)
 
INSERT [dbo].[Recipes] ([Id], [Name], [Description], [TotalCost], [AuthorUserName], [CookingTime], [CreatedAt], [ImageUrl], [Instructions], [PreparationTime], [Servings], [TotalTime], [UpdatedAt]) VALUES (4, N'Sałatka z awokado, pomidorem i feta', N'1. Pokrój awokado, pomidora i ser feta. 2. Wymieszaj składniki w misce z sałatą. 3. Skrop oliwa z oliwek i sokiem z cytryny, dopraw solą i pieprzem.', CAST(12.76 AS Decimal(18, 2)), N'Richy', CAST(N'00:00:30' AS Time), CAST(N'0001-01-01T00:00:00.0000000' AS DateTime2), NULL, N'1.Kup produkty. 2.Przy tuj potrawe.', CAST(N'00:00:15' AS Time), 2, CAST(N'00:00:45' AS Time), NULL)
 
INSERT [dbo].[Recipes] ([Id], [Name], [Description], [TotalCost], [AuthorUserName], [CookingTime], [CreatedAt], [ImageUrl], [Instructions], [PreparationTime], [Servings], [TotalTime], [UpdatedAt]) VALUES (5, N'Zupa jarzynowa z soczewica', N'1. podsmaż cebule i czosnek, dodaj ziemniaki i marchew. 2. Dodaj soczewice i pomidory w puszce. 3. Dopraw tymiankiem, lisciem laurowym, solą i pieprzem. 4.  tuj na średnim ogniu, az warzywa beda miekkie.', CAST(7.81 AS Decimal(18, 2)), N'Richy', CAST(N'00:00:30' AS Time), CAST(N'0001-01-01T00:00:00.0000000' AS DateTime2), NULL, N'1.Kup produkty. 2.Przy tuj potrawe.', CAST(N'00:00:15' AS Time), 2, CAST(N'00:00:45' AS Time), NULL)
 
INSERT [dbo].[Recipes] ([Id], [Name], [Description], [TotalCost], [AuthorUserName], [CookingTime], [CreatedAt], [ImageUrl], [Instructions], [PreparationTime], [Servings], [TotalTime], [UpdatedAt]) VALUES (6, N'Łosoś pieczony z cukinia', N'1. Natrzyj łososia solą i pieprzem. 2. Ułóż plastry cukinii na blasze, polóz na nich łososia. 3. Posyp koperkiem i skropl oliwa z oliwek. 4. Piecz w 180°C przez 20 minut.', CAST(46.56 AS Decimal(18, 2)), N'Richy', CAST(N'00:00:30' AS Time), CAST(N'0001-01-01T00:00:00.0000000' AS DateTime2), NULL, N'1.Kup produkty. 2.Przy tuj potrawe.', CAST(N'00:00:15' AS Time), 2, CAST(N'00:00:45' AS Time), NULL)
 
INSERT [dbo].[Recipes] ([Id], [Name], [Description], [TotalCost], [AuthorUserName], [CookingTime], [CreatedAt], [ImageUrl], [Instructions], [PreparationTime], [Servings], [TotalTime], [UpdatedAt]) VALUES (7, N'Frittata z warzywami i serem', N'1. Podsmaż cebule i papryke na oliwie. 2. Dodaj brokul i smaż przez kilka minut. 3. Wlej roztrzepane jajka, dodaj ser  uda. 4. Piecz w piekarniku nagrzanym do 180°C przez 15 minut.', CAST(3.51 AS Decimal(18, 2)), N'Richy', CAST(N'00:00:30' AS Time), CAST(N'0001-01-01T00:00:00.0000000' AS DateTime2), NULL, N'1.Kup produkty. 2.Przy tuj potrawe.', CAST(N'00:00:15' AS Time), 2, CAST(N'00:00:45' AS Time), NULL)
 
INSERT [dbo].[Recipes] ([Id], [Name], [Description], [TotalCost], [AuthorUserName], [CookingTime], [CreatedAt], [ImageUrl], [Instructions], [PreparationTime], [Servings], [TotalTime], [UpdatedAt]) VALUES (8, N'Pieczone bataty z hummusem', N'1. Pokrój bataty na kawalki, skropl oliwa, posyp solą i pieprzem, piecz w 200°C przez 25 minut. 2. Przy tuj hummus: zmiksuj ciecierzyce z czosnkiem, tahini, sokiem z cytryny, solą i pieprzem. 3. Podawaj bataty z hummusem.', CAST(9.64 AS Decimal(18, 2)), N'Richy', CAST(N'00:00:30' AS Time), CAST(N'0001-01-01T00:00:00.0000000' AS DateTime2), NULL, N'1.Kup produkty. 2.Przy tuj potrawe.', CAST(N'00:00:15' AS Time), 2, CAST(N'00:00:45' AS Time), NULL)
 
INSERT [dbo].[Recipes] ([Id], [Name], [Description], [TotalCost], [AuthorUserName], [CookingTime], [CreatedAt], [ImageUrl], [Instructions], [PreparationTime], [Servings], [TotalTime], [UpdatedAt]) VALUES (9, N'Sałatka z quinoa i warzywami', N'1. Ugotuj quinoa z dnie z instrukcja na opakowaniu. 2. Pokrój ogórka i pomidora, wymieszaj z quinoa. 3. Dodaj orzechy, skropl sokiem z cytryny i oliwa. 4. Dopraw solą i pieprzem, podawaj schlodzona.', CAST(5.75 AS Decimal(18, 2)), N'Richy', CAST(N'00:00:30' AS Time), CAST(N'0001-01-01T00:00:00.0000000' AS DateTime2), NULL, N'1.Kup produkty. 2.Przy tuj potrawe.', CAST(N'00:00:15' AS Time), 2, CAST(N'00:00:45' AS Time), NULL)
 
INSERT [dbo].[Recipes] ([Id], [Name], [Description], [TotalCost], [AuthorUserName], [CookingTime], [CreatedAt], [ImageUrl], [Instructions], [PreparationTime], [Servings], [TotalTime], [UpdatedAt]) VALUES (10, N'Spaghetti z sosem pomidorowym i bazylia', N'1. Ugotuj makaron spaghetti. 2. podsmaż czosnek na oliwie, dodaj pomidory w puszce. 3. Dopraw solą i pieprzem,  tuj przez 10 minut. 4. Wymieszaj z u towanym makaronem, posyp bazylia i parmezanem.', CAST(10.49 AS Decimal(18, 2)), N'Richy', CAST(N'00:00:30' AS Time), CAST(N'0001-01-01T00:00:00.0000000' AS DateTime2), NULL, N'1.Kup produkty. 2.Przy tuj potrawe.', CAST(N'00:00:15' AS Time), 2, CAST(N'00:00:45' AS Time), NULL)
 
INSERT [dbo].[Recipes] ([Id], [Name], [Description], [TotalCost], [AuthorUserName], [CookingTime], [CreatedAt], [ImageUrl], [Instructions], [PreparationTime], [Servings], [TotalTime], [UpdatedAt]) VALUES (11, N'Chili con carne', N'1. Podsmaż cebule i czosnek na oleju. 2. Dodaj wołowinę i smaż do zarumienienia. 3. Dodaj papryke, pomidory i fasole. 4. Dopraw chili, kuminem, solą i pieprzem. 5.  tuj na malym ogniu przez 30 minut.', CAST(34.14 AS Decimal(18, 2)), N'Richy', CAST(N'00:00:30' AS Time), CAST(N'0001-01-01T00:00:00.0000000' AS DateTime2), NULL, N'1.Kup produkty. 2.Przy tuj potrawe.', CAST(N'00:00:15' AS Time), 2, CAST(N'00:00:45' AS Time), NULL)
 
INSERT [dbo].[Recipes] ([Id], [Name], [Description], [TotalCost], [AuthorUserName], [CookingTime], [CreatedAt], [ImageUrl], [Instructions], [PreparationTime], [Servings], [TotalTime], [UpdatedAt]) VALUES (12, N'Pieczona wieprzowina z ziemniakami i rozmarynem', N'1. Natrzyj wieprzowine solą, pieprzem i czosnkiem. 2. Ułóż na blasze z ziemniakami i posyp rozmarynem. 3. Piecz w 200°C przez 1  dzine.', CAST(21.88 AS Decimal(18, 2)), N'Richy', CAST(N'00:00:30' AS Time), CAST(N'0001-01-01T00:00:00.0000000' AS DateTime2), NULL, N'1.Kup produkty. 2.Przy tuj potrawe.', CAST(N'00:00:15' AS Time), 2, CAST(N'00:00:45' AS Time), NULL)
 
INSERT [dbo].[Recipes] ([Id], [Name], [Description], [TotalCost], [AuthorUserName], [CookingTime], [CreatedAt], [ImageUrl], [Instructions], [PreparationTime], [Servings], [TotalTime], [UpdatedAt]) VALUES (13, N'Risotto z grzybami', N'1. Podsmaż cebule i czosnek na oliwie, dodaj ryż i smaż przez 2 minuty. 2. Stopniowo dodawaj bulion, ciagle mieszajac. 3. Dodaj pokrojone pieczarki. 4.  tuj, az ryż bedzie kremowy, dodaj parmezan. 5. Dopraw solą i pieprzem.', CAST(17.51 AS Decimal(18, 2)), N'Richy', CAST(N'00:00:30' AS Time), CAST(N'0001-01-01T00:00:00.0000000' AS DateTime2), NULL, N'1.Kup produkty. 2.Przy tuj potrawe.', CAST(N'00:00:15' AS Time), 2, CAST(N'00:00:45' AS Time), NULL)
 
INSERT [dbo].[Recipes] ([Id], [Name], [Description], [TotalCost], [AuthorUserName], [CookingTime], [CreatedAt], [ImageUrl], [Instructions], [PreparationTime], [Servings], [TotalTime], [UpdatedAt]) VALUES (14, N'Zapiekanka ziemniaczana z serem i boczkiem', N'1. Pokrój ziemniaki i cebule w cienkie plastry. 2. Ułóż warstwy ziemniaków, cebuli, boczku i sera w naczyniu. 3. Skrop śmietaną i dopraw. 4. Piecz w 180°C przez 40 minut.', CAST(7.76 AS Decimal(18, 2)), N'Richy', CAST(N'00:00:30' AS Time), CAST(N'0001-01-01T00:00:00.0000000' AS DateTime2), NULL, N'1.Kup produkty. 2.Przy tuj potrawe.', CAST(N'00:00:15' AS Time), 2, CAST(N'00:00:45' AS Time), NULL)
 
INSERT [dbo].[Recipes] ([Id], [Name], [Description], [TotalCost], [AuthorUserName], [CookingTime], [CreatedAt], [ImageUrl], [Instructions], [PreparationTime], [Servings], [TotalTime], [UpdatedAt]) VALUES (15, N'Tortilla z kurczakiem i warzywami', N'1. Grilluj kurczaka i pokrój w paski. 2. podsmaż papryke i cebule na oliwie. 3. Posmaruj tortille sosem czosnkowym. 4. Nalóz warzywa, kurczaka i salate. 5. Zwiń i podawaj.', CAST(12.88 AS Decimal(18, 2)), N'Richy', CAST(N'00:00:30' AS Time), CAST(N'0001-01-01T00:00:00.0000000' AS DateTime2), NULL, N'1.Kup produkty. 2.Przy tuj potrawe.', CAST(N'00:00:15' AS Time), 2, CAST(N'00:00:45' AS Time), NULL)
 
INSERT [dbo].[Recipes] ([Id], [Name], [Description], [TotalCost], [AuthorUserName], [CookingTime], [CreatedAt], [ImageUrl], [Instructions], [PreparationTime], [Servings], [TotalTime], [UpdatedAt]) VALUES (16, N'Lasagne z miesem mielonym', N'1. podsmaż cebule, czosnek i mięso. 2. Dodaj pomidory i oregano,  tuj 15 minut. 3. Ukladaj warstwy makaronu, miesa, beszamelu i sera. 4. Piecz w 180°C przez 30 minut.', CAST(47.59 AS Decimal(18, 2)), N'Richy', CAST(N'00:00:30' AS Time), CAST(N'0001-01-01T00:00:00.0000000' AS DateTime2), NULL, N'1.Kup produkty. 2.Przy tuj potrawe.', CAST(N'00:00:15' AS Time), 2, CAST(N'00:00:45' AS Time), NULL)
 
INSERT [dbo].[Recipes] ([Id], [Name], [Description], [TotalCost], [AuthorUserName], [CookingTime], [CreatedAt], [ImageUrl], [Instructions], [PreparationTime], [Servings], [TotalTime], [UpdatedAt]) VALUES (17, N'Grillowane warzywa z feta i ziolami', N'1. Pokrój warzywa i grilluj na patelni. 2. Posyp feta i ziolami. 3. Skrop oliwa i dopraw do smaku. 4. Podawaj na ciepło lub zimno.', CAST(9.13 AS Decimal(18, 2)), N'Richy', CAST(N'00:00:30' AS Time), CAST(N'0001-01-01T00:00:00.0000000' AS DateTime2), NULL, N'1.Kup produkty. 2.Przy tuj potrawe.', CAST(N'00:00:15' AS Time), 2, CAST(N'00:00:45' AS Time), NULL)
 
INSERT [dbo].[Recipes] ([Id], [Name], [Description], [TotalCost], [AuthorUserName], [CookingTime], [CreatedAt], [ImageUrl], [Instructions], [PreparationTime], [Servings], [TotalTime], [UpdatedAt]) VALUES (18, N'Sałatka z brokułem i jajkiem', N'1. Ugotuj brokul i jajka na twardo. 2. Pokrój jajka i wymieszaj z brokułem. 3. Przy tuj sos z jogurtu i czosnku, dopraw solą i pieprzem. 4. Polej sałatkę sosem i posyp natka.', CAST(2.63 AS Decimal(18, 2)), N'Richy', CAST(N'00:00:30' AS Time), CAST(N'0001-01-01T00:00:00.0000000' AS DateTime2), NULL, N'1.Kup produkty. 2.Przy tuj potrawe.', CAST(N'00:00:15' AS Time), 2, CAST(N'00:00:45' AS Time), NULL)
 
INSERT [dbo].[Recipes] ([Id], [Name], [Description], [TotalCost], [AuthorUserName], [CookingTime], [CreatedAt], [ImageUrl], [Instructions], [PreparationTime], [Servings], [TotalTime], [UpdatedAt]) VALUES (19, N'Pasta z awokado i jajkiem', N'1. Rozgniec awokado i u towane jajka. 2. Dodaj przecisniety czosnek i sok z cytryny. 3. Dopraw solą i pieprzem, wymieszaj.', CAST(0.54 AS Decimal(18, 2)), N'Richy', CAST(N'00:00:30' AS Time), CAST(N'0001-01-01T00:00:00.0000000' AS DateTime2), NULL, N'1.Kup produkty. 2.Przy tuj potrawe.', CAST(N'00:00:15' AS Time), 2, CAST(N'00:00:45' AS Time), NULL)
 
INSERT [dbo].[Recipes] ([Id], [Name], [Description], [TotalCost], [AuthorUserName], [CookingTime], [CreatedAt], [ImageUrl], [Instructions], [PreparationTime], [Servings], [TotalTime], [UpdatedAt]) VALUES (20, N'Bolognese z makaronem penne', N'1. Podsmaż cebule i czosnek, dodaj mięso. 2. Dodaj pomidory i oregano,  tuj 20 minut. 3. Ugotuj makaron. 4. Podawaj makaron z sosem i posyp parmezanem.', CAST(36.18 AS Decimal(18, 2)), N'Richy', CAST(N'00:00:30' AS Time), CAST(N'0001-01-01T00:00:00.0000000' AS DateTime2), NULL, N'1.Kup produkty. 2.Przy tuj potrawe.', CAST(N'00:00:15' AS Time), 2, CAST(N'00:00:45' AS Time), NULL)
 
INSERT [dbo].[Recipes] ([Id], [Name], [Description], [TotalCost], [AuthorUserName], [CookingTime], [CreatedAt], [ImageUrl], [Instructions], [PreparationTime], [Servings], [TotalTime], [UpdatedAt]) VALUES (21, N'Zupa krem z dyni', N'1. Podsmaż cebule i imbir na oliwie. 2. Dodaj dynie i bulion,  tuj do miekkosci. 3. Zmiksuj zupe na gładki krem, dodaj śmietane. 4. Dopraw solą i pieprzem.', CAST(17.49 AS Decimal(18, 2)), N'Richy', CAST(N'00:00:30' AS Time), CAST(N'0001-01-01T00:00:00.0000000' AS DateTime2), NULL, N'1.Kup produkty. 2.Przy tuj potrawe.', CAST(N'00:00:15' AS Time), 2, CAST(N'00:00:45' AS Time), NULL)
 
INSERT [dbo].[Recipes] ([Id], [Name], [Description], [TotalCost], [AuthorUserName], [CookingTime], [CreatedAt], [ImageUrl], [Instructions], [PreparationTime], [Servings], [TotalTime], [UpdatedAt]) VALUES (22, N'Kotlety z ciecierzycy i szpinaku', N'1. Zblenduj ciecierzyce z cebula i czosnkiem. 2. Dodaj posiekany szpinak, jajka i bulke tarta, dopraw. 3. Formuj kotlety i smaż na oleju rzepakowym.', CAST(4.33 AS Decimal(18, 2)), N'Richy', CAST(N'00:00:30' AS Time), CAST(N'0001-01-01T00:00:00.0000000' AS DateTime2), NULL, N'1.Kup produkty. 2.Przy tuj potrawe.', CAST(N'00:00:15' AS Time), 2, CAST(N'00:00:45' AS Time), NULL)
 
INSERT [dbo].[Recipes] ([Id], [Name], [Description], [TotalCost], [AuthorUserName], [CookingTime], [CreatedAt], [ImageUrl], [Instructions], [PreparationTime], [Servings], [TotalTime], [UpdatedAt]) VALUES (23, N'Krewetki w sosie czosnkowym', N'1. Podsmaż czosnek na oliwie. 2. Dodaj krewetki i smaż przez 3-4 minuty. 3. Skrop sokiem z cytryny, posyp natka pietruszki, dopraw solą i pieprzem.', CAST(9.10 AS Decimal(18, 2)), N'Richy', CAST(N'00:00:30' AS Time), CAST(N'0001-01-01T00:00:00.0000000' AS DateTime2), NULL, N'1.Kup produkty. 2.Przy tuj potrawe.', CAST(N'00:00:15' AS Time), 2, CAST(N'00:00:45' AS Time), NULL)
 
INSERT [dbo].[Recipes] ([Id], [Name], [Description], [TotalCost], [AuthorUserName], [CookingTime], [CreatedAt], [ImageUrl], [Instructions], [PreparationTime], [Servings], [TotalTime], [UpdatedAt]) VALUES (24, N'Sałatka z kasza jaglana i pomarancza', N'1. Ugotuj kasze jaglana i ostudz. 2. Obierz pomarancze i pokrój w kawalki. 3. Wymieszaj kasze z pomarancza, dodaj miete, miód i sok z cytryny. 4. Dopraw solą i pieprzem.', CAST(3.72 AS Decimal(18, 2)), N'Richy', CAST(N'00:00:30' AS Time), CAST(N'0001-01-01T00:00:00.0000000' AS DateTime2), NULL, N'1.Kup produkty. 2.Przy tuj potrawe.', CAST(N'00:00:15' AS Time), 2, CAST(N'00:00:45' AS Time), NULL)
 
INSERT [dbo].[Recipes] ([Id], [Name], [Description], [TotalCost], [AuthorUserName], [CookingTime], [CreatedAt], [ImageUrl], [Instructions], [PreparationTime], [Servings], [TotalTime], [UpdatedAt]) VALUES (25, N'Zapiekanka makaronowa z szynka i serem', N'1. Ugotuj makaron al dente. 2. podsmaż cebule, dodaj szynke i śmietane, dopraw solą i pieprzem. 3. Wymieszaj z makaronem, przełóż do naczynia, posyp serem. 4. Piecz w 180°C przez 25 minut.', CAST(10.11 AS Decimal(18, 2)), N'Richy', CAST(N'00:00:30' AS Time), CAST(N'0001-01-01T00:00:00.0000000' AS DateTime2), NULL, N'1.Kup produkty. 2.Przy tuj potrawe.', CAST(N'00:00:15' AS Time), 2, CAST(N'00:00:45' AS Time), NULL)
 
INSERT [dbo].[Recipes] ([Id], [Name], [Description], [TotalCost], [AuthorUserName], [CookingTime], [CreatedAt], [ImageUrl], [Instructions], [PreparationTime], [Servings], [TotalTime], [UpdatedAt]) VALUES (26, N'Tarta z pomidorami i serem pleśniowym', N'1. Rozlóz ciasto francuskie na blasze i nakluj widelcem. 2. Ułóż pokrojone pomidory i ser pleśniowy na ciescie. 3. Posyp bazylia, skropl oliwa, dopraw solą i pieprzem. 4. Piecz w 180°C przez 20 minut.', CAST(6.35 AS Decimal(18, 2)), N'Richy', CAST(N'00:00:30' AS Time), CAST(N'0001-01-01T00:00:00.0000000' AS DateTime2), NULL, N'1.Kup produkty. 2.Przy tuj potrawe.', CAST(N'00:00:15' AS Time), 2, CAST(N'00:00:45' AS Time), NULL)
 
INSERT [dbo].[Recipes] ([Id], [Name], [Description], [TotalCost], [AuthorUserName], [CookingTime], [CreatedAt], [ImageUrl], [Instructions], [PreparationTime], [Servings], [TotalTime], [UpdatedAt]) VALUES (27, N'Smażona kapusta z ziemniakami i boczkiem', N'1. Podsmaż boczek na patelni. 2. Dodaj pokrojona cebule i smaż do zeszklenia. 3. Dodaj kapuste i ziemniaki, dopraw solą i pieprzem. 4. smaż na średnim ogniu przez 15 minut.', CAST(28.65 AS Decimal(18, 2)), N'Richy', CAST(N'00:00:30' AS Time), CAST(N'0001-01-01T00:00:00.0000000' AS DateTime2), NULL, N'1.Kup produkty. 2.Przy tuj potrawe.', CAST(N'00:00:15' AS Time), 2, CAST(N'00:00:45' AS Time), NULL)
 
INSERT [dbo].[Recipes] ([Id], [Name], [Description], [TotalCost], [AuthorUserName], [CookingTime], [CreatedAt], [ImageUrl], [Instructions], [PreparationTime], [Servings], [TotalTime], [UpdatedAt]) VALUES (28, N'Sałatka z Łosośiem i awokado', N'1. Pokrój awokado i łososia. 2. Wymieszaj salate z awokado i Łosośiem. 3. Skrop sokiem z cytryny i oliwa, dopraw solą i pieprzem.', CAST(14.24 AS Decimal(18, 2)), N'Richy', CAST(N'00:00:30' AS Time), CAST(N'0001-01-01T00:00:00.0000000' AS DateTime2), NULL, N'1.Kup produkty. 2.Przy tuj potrawe.', CAST(N'00:00:15' AS Time), 2, CAST(N'00:00:45' AS Time), NULL)
 
INSERT [dbo].[Recipes] ([Id], [Name], [Description], [TotalCost], [AuthorUserName], [CookingTime], [CreatedAt], [ImageUrl], [Instructions], [PreparationTime], [Servings], [TotalTime], [UpdatedAt]) VALUES (29, N'Gulasz wolowy z papryka', N'1. Podsmaż cebule i czosnek na oliwie. 2. Dodaj wołowinę i smaż do zarumienienia. 3. Dodaj pokrojona papryke, liść laurowy, papryke slodka, sól i pieprz. 4. Duś pod przykryciem przez 1,5  dziny.', CAST(33.32 AS Decimal(18, 2)), N'Richy', CAST(N'00:00:30' AS Time), CAST(N'0001-01-01T00:00:00.0000000' AS DateTime2), NULL, N'1.Kup produkty. 2.Przy tuj potrawe.', CAST(N'00:00:15' AS Time), 2, CAST(N'00:00:45' AS Time), NULL)
 
INSERT [dbo].[Recipes] ([Id], [Name], [Description], [TotalCost], [AuthorUserName], [CookingTime], [CreatedAt], [ImageUrl], [Instructions], [PreparationTime], [Servings], [TotalTime], [UpdatedAt]) VALUES (30, N'Zupa pomidorowa z ryżem', N'1. Podsmaż cebule na oliwie. 2. Dodaj pomidory i bulion,  tuj przez 15 minut. 3. Ugotuj ryż. 4. Dodaj śmietane do zupy, dopraw solą, pieprzem i cukrem. 5. Podawaj z ryżem.', CAST(15.01 AS Decimal(18, 2)), N'Richy', CAST(N'00:00:30' AS Time), CAST(N'0001-01-01T00:00:00.0000000' AS DateTime2), NULL, N'1.Kup produkty. 2.Przy tuj potrawe.', CAST(N'00:00:15' AS Time), 2, CAST(N'00:00:45' AS Time), NULL)
 
INSERT [dbo].[Recipes] ([Id], [Name], [Description], [TotalCost], [AuthorUserName], [CookingTime], [CreatedAt], [ImageUrl], [Instructions], [PreparationTime], [Servings], [TotalTime], [UpdatedAt]) VALUES (31, N'Kotlety z kalafiora', N'1. Ugotuj kalafior i rozgniec widelcem. 2. Dodaj jajka, bulke tarta, posiekana cebule i pietruszke, dopraw solą i pieprzem. 3. Formuj kotlety i smaż na oleju z obu stron.', CAST(7.48 AS Decimal(18, 2)), N'Richy', CAST(N'00:00:30' AS Time), CAST(N'0001-01-01T00:00:00.0000000' AS DateTime2), NULL, N'1.Kup produkty. 2.Przy tuj potrawe.', CAST(N'00:00:15' AS Time), 2, CAST(N'00:00:45' AS Time), NULL)
 
INSERT [dbo].[Recipes] ([Id], [Name], [Description], [TotalCost], [AuthorUserName], [CookingTime], [CreatedAt], [ImageUrl], [Instructions], [PreparationTime], [Servings], [TotalTime], [UpdatedAt]) VALUES (32, N'Makaron z pieczarkami i śmietaną', N'1. Ugotuj makaron al dente. 2. podsmaż pieczarki i czosnek na oliwie. 3. Dodaj śmietane i  tuj przez 5 minut. 4. Dopraw solą i pieprzem. 5. Wymieszaj z makaronem i posyp parmezanem.', CAST(11.46 AS Decimal(18, 2)), N'Richy', CAST(N'00:00:30' AS Time), CAST(N'0001-01-01T00:00:00.0000000' AS DateTime2), NULL, N'1.Kup produkty. 2.Przy tuj potrawe.', CAST(N'00:00:15' AS Time), 2, CAST(N'00:00:45' AS Time), NULL)
 
INSERT [dbo].[Recipes] ([Id], [Name], [Description], [TotalCost], [AuthorUserName], [CookingTime], [CreatedAt], [ImageUrl], [Instructions], [PreparationTime], [Servings], [TotalTime], [UpdatedAt]) VALUES (33, N'Zapiekanka ryzowa z kurczakiem i warzywami', N'1. Ugotuj ryż. 2. podsmaż kurczaka z cebula, dodaj papryke i cukinie, dopraw solą i pieprzem. 3. Wymieszaj ryż z kurczakiem i warzywami. 4. Przełóż do naczynia, posyp serem i piecz w 180°C przez 20 minut.', CAST(12.33 AS Decimal(18, 2)), N'Richy', CAST(N'00:00:30' AS Time), CAST(N'0001-01-01T00:00:00.0000000' AS DateTime2), NULL, N'1.Kup produkty. 2.Przy tuj potrawe.', CAST(N'00:00:15' AS Time), 2, CAST(N'00:00:45' AS Time), NULL)
 
INSERT [dbo].[Recipes] ([Id], [Name], [Description], [TotalCost], [AuthorUserName], [CookingTime], [CreatedAt], [ImageUrl], [Instructions], [PreparationTime], [Servings], [TotalTime], [UpdatedAt]) VALUES (34, N'Sałatka grecka', N'1. Pokrój warzywa i fete, wymieszaj z oliwkami. 2. Skrop oliwa, dopraw solą, pieprzem i oregano. 3. Podawaj schlodzona.', CAST(11.65 AS Decimal(18, 2)), N'Richy', CAST(N'00:00:30' AS Time), CAST(N'0001-01-01T00:00:00.0000000' AS DateTime2), NULL, N'1.Kup produkty. 2.Przy tuj potrawe.', CAST(N'00:00:15' AS Time), 2, CAST(N'00:00:45' AS Time), NULL)
 
INSERT [dbo].[Recipes] ([Id], [Name], [Description], [TotalCost], [AuthorUserName], [CookingTime], [CreatedAt], [ImageUrl], [Instructions], [PreparationTime], [Servings], [TotalTime], [UpdatedAt]) VALUES (35, N'Zupa krem z brokula', N'1. Podsmaż cebule na oliwie, dodaj brokula i bulion. 2.  tuj do miekkosci brokula, zmiksuj zupe na krem. 3. Dodaj śmietane i dopraw. 4. Podawaj z grzankami.', CAST(12.89 AS Decimal(18, 2)), N'Richy', CAST(N'00:00:30' AS Time), CAST(N'0001-01-01T00:00:00.0000000' AS DateTime2), NULL, N'1.Kup produkty. 2.Przy tuj potrawe.', CAST(N'00:00:15' AS Time), 2, CAST(N'00:00:45' AS Time), NULL)
 
INSERT [dbo].[Recipes] ([Id], [Name], [Description], [TotalCost], [AuthorUserName], [CookingTime], [CreatedAt], [ImageUrl], [Instructions], [PreparationTime], [Servings], [TotalTime], [UpdatedAt]) VALUES (36, N'Kotlety mielone z ziemniakami i marchewka', N'1. Wymieszaj mięso mielone z posiekana cebula, jajkiem, bułką tartą, solą i pieprzem. 2. Formuj kotlety i smaż na oleju. 3. Ugotuj ziemniaki i marchew. 4. Podawaj kotlety z ziemniakami i marchewka.', CAST(28.24 AS Decimal(18, 2)), N'Richy', CAST(N'00:00:30' AS Time), CAST(N'0001-01-01T00:00:00.0000000' AS DateTime2), NULL, N'1.Kup produkty. 2.Przy tuj potrawe.', CAST(N'00:00:15' AS Time), 2, CAST(N'00:00:45' AS Time), NULL)
 
INSERT [dbo].[Recipes] ([Id], [Name], [Description], [TotalCost], [AuthorUserName], [CookingTime], [CreatedAt], [ImageUrl], [Instructions], [PreparationTime], [Servings], [TotalTime], [UpdatedAt]) VALUES (37, N'Makaron z pesto i pomidorami cherry', N'1. Ugotuj makaron al dente. 2. Zmiksuj bazylie, czosnek, parmezan i oliwe na pesto. 3. Wymieszaj makaron z pesto i pokrojonymi pomidorami cherry. 4. Dopraw solą i pieprzem, podawaj od razu.', CAST(14.24 AS Decimal(18, 2)), N'Richy', CAST(N'00:00:30' AS Time), CAST(N'0001-01-01T00:00:00.0000000' AS DateTime2), NULL, N'1.Kup produkty. 2.Przy tuj potrawe.', CAST(N'00:00:15' AS Time), 2, CAST(N'00:00:45' AS Time), NULL)
 
INSERT [dbo].[Recipes] ([Id], [Name], [Description], [TotalCost], [AuthorUserName], [CookingTime], [CreatedAt], [ImageUrl], [Instructions], [PreparationTime], [Servings], [TotalTime], [UpdatedAt]) VALUES (38, N'Smażone tofu z warzywami i ryżem', N'1. Ugotuj ryż. 2. podsmaż tofu na oliwie, dodaj warzywa i smaż przez 5 minut. 3. Dodaj sos sojowy i czosnek, dopraw solą i pieprzem. 4. Podawaj z ryżem.', CAST(7.41 AS Decimal(18, 2)), N'Richy', CAST(N'00:00:30' AS Time), CAST(N'0001-01-01T00:00:00.0000000' AS DateTime2), NULL, N'1.Kup produkty. 2.Przy tuj potrawe.', CAST(N'00:00:15' AS Time), 2, CAST(N'00:00:45' AS Time), NULL)
 
INSERT [dbo].[Recipes] ([Id], [Name], [Description], [TotalCost], [AuthorUserName], [CookingTime], [CreatedAt], [ImageUrl], [Instructions], [PreparationTime], [Servings], [TotalTime], [UpdatedAt]) VALUES (39, N'Pieczona ryba z warzywami i cytryna', N'1. Ułóż rybe na blasze, posyp solą i pieprzem. 2. Ułóż pokrojone warzywa obok, skropl oliwa i sokiem z cytryny. 3. Piecz w 180°C przez 20 minut.', CAST(38.23 AS Decimal(18, 2)), N'Richy', CAST(N'00:00:30' AS Time), CAST(N'0001-01-01T00:00:00.0000000' AS DateTime2), NULL, N'1.Kup produkty. 2.Przy tuj potrawe.', CAST(N'00:00:15' AS Time), 2, CAST(N'00:00:45' AS Time), NULL)
 
INSERT [dbo].[Recipes] ([Id], [Name], [Description], [TotalCost], [AuthorUserName], [CookingTime], [CreatedAt], [ImageUrl], [Instructions], [PreparationTime], [Servings], [TotalTime], [UpdatedAt]) VALUES (40, N'Zupa krem z cukinii i bazylii', N'1. Podsmaż cebule na oliwie, dodaj cukinie i bulion. 2.  tuj do miekkosci, zmiksuj na gładki krem. 3. Dodaj śmietane, bazylie i dopraw. 4. Podawaj na ciepło.', CAST(12.18 AS Decimal(18, 2)), N'Richy', CAST(N'00:00:30' AS Time), CAST(N'0001-01-01T00:00:00.0000000' AS DateTime2), NULL, N'1.Kup produkty. 2.Przy tuj potrawe.', CAST(N'00:00:15' AS Time), 2, CAST(N'00:00:45' AS Time), NULL)
 
INSERT [dbo].[Recipes] ([Id], [Name], [Description], [TotalCost], [AuthorUserName], [CookingTime], [CreatedAt], [ImageUrl], [Instructions], [PreparationTime], [Servings], [TotalTime], [UpdatedAt]) VALUES (41, N'Zapiekanka z makaronem i szpinakiem', N'1. Ugotuj makaron al dente. 2. podsmaż cebule i szpinak na oliwie. 3. Wymieszaj z makaronem, śmietaną i serem feta. 4. Przełóż do naczynia, piecz w 180°C przez 20 minut.', CAST(15.31 AS Decimal(18, 2)), N'Richy', CAST(N'00:00:30' AS Time), CAST(N'0001-01-01T00:00:00.0000000' AS DateTime2), NULL, N'1.Kup produkty. 2.Przy tuj potrawe.', CAST(N'00:00:15' AS Time), 2, CAST(N'00:00:45' AS Time), NULL)
 
INSERT [dbo].[Recipes] ([Id], [Name], [Description], [TotalCost], [AuthorUserName], [CookingTime], [CreatedAt], [ImageUrl], [Instructions], [PreparationTime], [Servings], [TotalTime], [UpdatedAt]) VALUES (42, N'Kuskus z warzywami i kurczakiem', N'1. Ugotuj kuskus wedlug instrukcji. 2. podsmaż kurczaka z cebula, dodaj warzywa i smaż przez 5 minut. 3. Wymieszaj z kuskusem, dopraw solą, pieprzem i sokiem z cytryny.', CAST(8.54 AS Decimal(18, 2)), N'Richy', CAST(N'00:00:30' AS Time), CAST(N'0001-01-01T00:00:00.0000000' AS DateTime2), NULL, N'1.Kup produkty. 2.Przy tuj potrawe.', CAST(N'00:00:15' AS Time), 2, CAST(N'00:00:45' AS Time), NULL)
 
INSERT [dbo].[Recipes] ([Id], [Name], [Description], [TotalCost], [AuthorUserName], [CookingTime], [CreatedAt], [ImageUrl], [Instructions], [PreparationTime], [Servings], [TotalTime], [UpdatedAt]) VALUES (43, N'Sałatka z rukola, gruszka i serem pleśniowym', N'1. Pokrój gruszke i ser pleśniowy. 2. Wymieszaj rukole z gruszka, serem i orzechami. 3. Skrop oliwa, sokiem z cytryny i miodem, dopraw solą i pieprzem.', CAST(9.42 AS Decimal(18, 2)), N'Richy', CAST(N'00:00:30' AS Time), CAST(N'0001-01-01T00:00:00.0000000' AS DateTime2), NULL, N'1.Kup produkty. 2.Przy tuj potrawe.', CAST(N'00:00:15' AS Time), 2, CAST(N'00:00:45' AS Time), NULL)
 
INSERT [dbo].[Recipes] ([Id], [Name], [Description], [TotalCost], [AuthorUserName], [CookingTime], [CreatedAt], [ImageUrl], [Instructions], [PreparationTime], [Servings], [TotalTime], [UpdatedAt]) VALUES (44, N'Zupa fasolowa z kielbasa', N'1. Podsmaż cebule i czosnek, dodaj pokrojona kielbase. 2. Dodaj fasole, bulion i liść laurowy,  tuj przez 20 minut. 3. Dopraw solą i pieprzem, podawaj  raca.', CAST(25.00 AS Decimal(18, 2)), N'Richy', CAST(N'00:00:30' AS Time), CAST(N'0001-01-01T00:00:00.0000000' AS DateTime2), NULL, N'1.Kup produkty. 2.Przy tuj potrawe.', CAST(N'00:00:15' AS Time), 2, CAST(N'00:00:45' AS Time), NULL)
 
INSERT [dbo].[Recipes] ([Id], [Name], [Description], [TotalCost], [AuthorUserName], [CookingTime], [CreatedAt], [ImageUrl], [Instructions], [PreparationTime], [Servings], [TotalTime], [UpdatedAt]) VALUES (45, N'Nalesniki z serem i owocami', N'1. Wymieszaj make, mleko i jajka, usmaz nalesniki. 2. Nalóz serek na nalesniki, dodaj pokrojone owoce. 3. Złóż nalesniki i posyp cukrem pudrem.', CAST(6.62 AS Decimal(18, 2)), N'Richy', CAST(N'00:00:30' AS Time), CAST(N'0001-01-01T00:00:00.0000000' AS DateTime2), NULL, N'1.Kup produkty. 2.Przy tuj potrawe.', CAST(N'00:00:15' AS Time), 2, CAST(N'00:00:45' AS Time), NULL)
 
INSERT [dbo].[Recipes] ([Id], [Name], [Description], [TotalCost], [AuthorUserName], [CookingTime], [CreatedAt], [ImageUrl], [Instructions], [PreparationTime], [Servings], [TotalTime], [UpdatedAt]) VALUES (46, N'Szaszlyki drobiowe z warzywami', N'1. Pokrój kurczaka i warzywa, nadziej na patyczki. 2. Skrop oliwa, dopraw solą, pieprzem i ziolami. 3. Grilluj przez 10-15 minut, obracajac szaszłyki.', CAST(8.62 AS Decimal(18, 2)), N'Richy', CAST(N'00:00:30' AS Time), CAST(N'0001-01-01T00:00:00.0000000' AS DateTime2), NULL, N'1.Kup produkty. 2.Przy tuj potrawe.', CAST(N'00:00:15' AS Time), 2, CAST(N'00:00:45' AS Time), NULL)
 
INSERT [dbo].[Recipes] ([Id], [Name], [Description], [TotalCost], [AuthorUserName], [CookingTime], [CreatedAt], [ImageUrl], [Instructions], [PreparationTime], [Servings], [TotalTime], [UpdatedAt]) VALUES (47, N'Zupa krem z kalafiora i ziemniaków', N'1. Podsmaż cebule z imbirem na oliwie. 2. Dodaj kalafior, ziemniaki i bulion,  tuj do miekkosci. 3. Zmiksuj na gładki krem, dopraw solą i pieprzem.', CAST(17.09 AS Decimal(18, 2)), N'Richy', CAST(N'00:00:30' AS Time), CAST(N'0001-01-01T00:00:00.0000000' AS DateTime2), NULL, N'1.Kup produkty. 2.Przy tuj potrawe.', CAST(N'00:00:15' AS Time), 2, CAST(N'00:00:45' AS Time), NULL)
 
INSERT [dbo].[Recipes] ([Id], [Name], [Description], [TotalCost], [AuthorUserName], [CookingTime], [CreatedAt], [ImageUrl], [Instructions], [PreparationTime], [Servings], [TotalTime], [UpdatedAt]) VALUES (48, N'Pieczona papryka nadziewana ryżem i warzywami', N'1. Ugotuj ryż. 2. podsmaż cebule z marchewka i cukinia, dodaj do ryżu. 3. Napelnij papryki mieszanka ryzowa. 4. Piecz w 180°C przez 20-25 minut.', CAST(2.22 AS Decimal(18, 2)), N'Richy', CAST(N'00:00:30' AS Time), CAST(N'0001-01-01T00:00:00.0000000' AS DateTime2), NULL, N'1.Kup produkty. 2.Przy tuj potrawe.', CAST(N'00:00:15' AS Time), 2, CAST(N'00:00:45' AS Time), NULL)
 
INSERT [dbo].[Recipes] ([Id], [Name], [Description], [TotalCost], [AuthorUserName], [CookingTime], [CreatedAt], [ImageUrl], [Instructions], [PreparationTime], [Servings], [TotalTime], [UpdatedAt]) VALUES (49, N'Tosty francuskie z bananami i cynamonem', N'1. Wymieszaj jajka z mlekiem i cynamonem. 2. Maczaj chleb w mieszance i smaż na masle. 3. Podawaj z pokrojonymi bananami i posyp cukrem pudrem.', CAST(1.31 AS Decimal(18, 2)), N'Richy', CAST(N'00:00:30' AS Time), CAST(N'0001-01-01T00:00:00.0000000' AS DateTime2), NULL, N'1.Kup produkty. 2.Przy tuj potrawe.', CAST(N'00:00:15' AS Time), 2, CAST(N'00:00:45' AS Time), NULL)
 
INSERT [dbo].[Recipes] ([Id], [Name], [Description], [TotalCost], [AuthorUserName], [CookingTime], [CreatedAt], [ImageUrl], [Instructions], [PreparationTime], [Servings], [TotalTime], [UpdatedAt]) VALUES (50, N'Placuszki z cukinii i marchewki', N'1. Zetrzyj cukinie i marchew, odcisnij nadmiar wody. 2. Wymieszaj z jajkami, mąka, solą i pieprzem. 3. Formuj placuszki i smaż na oliwie z obu stron.', CAST(1.93 AS Decimal(18, 2)), N'Richy', CAST(N'00:00:30' AS Time), CAST(N'0001-01-01T00:00:00.0000000' AS DateTime2), NULL, N'1.Kup produkty. 2.Przy tuj potrawe.', CAST(N'00:00:15' AS Time), 2, CAST(N'00:00:45' AS Time), NULL)
 
INSERT [dbo].[Recipes] ([Id], [Name], [Description], [TotalCost], [AuthorUserName], [CookingTime], [CreatedAt], [ImageUrl], [Instructions], [PreparationTime], [Servings], [TotalTime], [UpdatedAt]) VALUES (51, N'Omlet z pieczarkami i serem', N'1. Podsmaż pieczarki i cebule na oliwie. 2. Roztrzep jajka z solą i pieprzem, wlej na patelnie. 3. Dodaj pieczarki i ser, smaż do sciecia omletu. 4. Złóż omlet na pól i podawaj.', CAST(5.32 AS Decimal(18, 2)), N'Richy', CAST(N'00:00:30' AS Time), CAST(N'0001-01-01T00:00:00.0000000' AS DateTime2), NULL, N'1.Kup produkty. 2.Przy tuj potrawe.', CAST(N'00:00:15' AS Time), 2, CAST(N'00:00:45' AS Time), NULL)
 
INSERT [dbo].[Recipes] ([Id], [Name], [Description], [TotalCost], [AuthorUserName], [CookingTime], [CreatedAt], [ImageUrl], [Instructions], [PreparationTime], [Servings], [TotalTime], [UpdatedAt]) VALUES (52, N'Pesto z bazylii z makaronem', N'1. Ugotuj makaron al dente. 2. Zmiksuj bazylie, czosnek, orzechy nerkowca, oliwe i parmezan, dopraw solą i pieprzem. 3. Wymieszaj makaron z pesto i podawaj.', CAST(12.38 AS Decimal(18, 2)), N'Richy', CAST(N'00:00:30' AS Time), CAST(N'0001-01-01T00:00:00.0000000' AS DateTime2), NULL, N'1.Kup produkty. 2.Przy tuj potrawe.', CAST(N'00:00:15' AS Time), 2, CAST(N'00:00:45' AS Time), NULL)
 
INSERT [dbo].[Recipes] ([Id], [Name], [Description], [TotalCost], [AuthorUserName], [CookingTime], [CreatedAt], [ImageUrl], [Instructions], [PreparationTime], [Servings], [TotalTime], [UpdatedAt]) VALUES (53, N'Zupa krem z batatów i imbiru', N'1. Podsmaż cebule na oliwie, dodaj starty imbir i pokrojone bataty. 2. Zalej woda i  tuj do miekkosci. 3. Zmiksuj na krem, dodaj mleko kokosowe i dopraw. 4. Podawaj na ciepło.', CAST(11.11 AS Decimal(18, 2)), N'Richy', CAST(N'00:00:30' AS Time), CAST(N'0001-01-01T00:00:00.0000000' AS DateTime2), NULL, N'1.Kup produkty. 2.Przy tuj potrawe.', CAST(N'00:00:15' AS Time), 2, CAST(N'00:00:45' AS Time), NULL)
 
INSERT [dbo].[Recipes] ([Id], [Name], [Description], [TotalCost], [AuthorUserName], [CookingTime], [CreatedAt], [ImageUrl], [Instructions], [PreparationTime], [Servings], [TotalTime], [UpdatedAt]) VALUES (54, N'Tarta z gruszka i  r nzola', N'1. Przy tuj ciasto z maki i oleju. 2. Pokrój gruszki i  r nzole. 3. Ułóż na ciescie, posyp solą i pieprzem. 4. Piecz w 180°C przez 20 minut.', CAST(9.23 AS Decimal(18, 2)), N'Richy', CAST(N'00:00:30' AS Time), CAST(N'0001-01-01T00:00:00.0000000' AS DateTime2), NULL, N'1.Kup produkty. 2.Przy tuj potrawe.', CAST(N'00:00:15' AS Time), 2, CAST(N'00:00:45' AS Time), NULL)
 
INSERT [dbo].[Recipes] ([Id], [Name], [Description], [TotalCost], [AuthorUserName], [CookingTime], [CreatedAt], [ImageUrl], [Instructions], [PreparationTime], [Servings], [TotalTime], [UpdatedAt]) VALUES (55, N'Pieczony bakłażan z sosem pomidorowym', N'1. Pokrój bakłażana i posól. 2. podsmaż cebule, dodaj pomidory i bazylie,  tuj 10 minut. 3. Ułóż bakłażana w naczyniu, polej sosem. 4. Piecz w 180°C przez 25 minut.', CAST(6.65 AS Decimal(18, 2)), N'Richy', CAST(N'00:00:30' AS Time), CAST(N'0001-01-01T00:00:00.0000000' AS DateTime2), NULL, N'1.Kup produkty. 2.Przy tuj potrawe.', CAST(N'00:00:15' AS Time), 2, CAST(N'00:00:45' AS Time), NULL)
 
INSERT [dbo].[Recipes] ([Id], [Name], [Description], [TotalCost], [AuthorUserName], [CookingTime], [CreatedAt], [ImageUrl], [Instructions], [PreparationTime], [Servings], [TotalTime], [UpdatedAt]) VALUES (56, N'Krem z zielone  groszku z mieta', N'1. Ugotuj groszek do miekkosci. 2. Dodaj zmiksowany czosnek, mleko kokosowe i miete. 3. Dopraw solą i pieprzem, zmiksuj na gładko.', CAST(6.29 AS Decimal(18, 2)), N'Richy', CAST(N'00:00:30' AS Time), CAST(N'0001-01-01T00:00:00.0000000' AS DateTime2), NULL, N'1.Kup produkty. 2.Przy tuj potrawe.', CAST(N'00:00:15' AS Time), 2, CAST(N'00:00:45' AS Time), NULL)
 
INSERT [dbo].[Recipes] ([Id], [Name], [Description], [TotalCost], [AuthorUserName], [CookingTime], [CreatedAt], [ImageUrl], [Instructions], [PreparationTime], [Servings], [TotalTime], [UpdatedAt]) VALUES (57, N'Placuszki z cukinii i serem feta', N'1. Zetrzyj cukinie, odsacz nadmiar wody. 2. Wymieszaj z jajkami, mąka i pokruszona feta. 3. Formuj placuszki i smaż na rozgrzanym oleju.', CAST(8.08 AS Decimal(18, 2)), N'Richy', CAST(N'00:00:30' AS Time), CAST(N'0001-01-01T00:00:00.0000000' AS DateTime2), NULL, N'1.Kup produkty. 2.Przy tuj potrawe.', CAST(N'00:00:15' AS Time), 2, CAST(N'00:00:45' AS Time), NULL)
 
INSERT [dbo].[Recipes] ([Id], [Name], [Description], [TotalCost], [AuthorUserName], [CookingTime], [CreatedAt], [ImageUrl], [Instructions], [PreparationTime], [Servings], [TotalTime], [UpdatedAt]) VALUES (58, N'Kaszotto z dynia i szpinakiem', N'1. Podsmaż cebule na oliwie, dodaj starty imbir i dynie. 2. Dodaj kasze i wode,  tuj do miekkosci. 3. Dodaj szpinak, dopraw i podawaj.', CAST(8.51 AS Decimal(18, 2)), N'Richy', CAST(N'00:00:30' AS Time), CAST(N'0001-01-01T00:00:00.0000000' AS DateTime2), NULL, N'1.Kup produkty. 2.Przy tuj potrawe.', CAST(N'00:00:15' AS Time), 2, CAST(N'00:00:45' AS Time), NULL)
 
INSERT [dbo].[Recipes] ([Id], [Name], [Description], [TotalCost], [AuthorUserName], [CookingTime], [CreatedAt], [ImageUrl], [Instructions], [PreparationTime], [Servings], [TotalTime], [UpdatedAt]) VALUES (59, N'Pasztet z soczewicy z marchewka', N'1. Podsmaż cebule i czosnek, dodaj starta marchewke. 2. Ugotuj soczewice, zmiksuj z warzywami. 3. Przełóż do formy i piecz w 180°C przez 30 minut.', CAST(4.14 AS Decimal(18, 2)), N'Richy', CAST(N'00:00:30' AS Time), CAST(N'0001-01-01T00:00:00.0000000' AS DateTime2), NULL, N'1.Kup produkty. 2.Przy tuj potrawe.', CAST(N'00:00:15' AS Time), 2, CAST(N'00:00:45' AS Time), NULL)
 
INSERT [dbo].[Recipes] ([Id], [Name], [Description], [TotalCost], [AuthorUserName], [CookingTime], [CreatedAt], [ImageUrl], [Instructions], [PreparationTime], [Servings], [TotalTime], [UpdatedAt]) VALUES (60, N'Ryż z warzywami i kurczakiem', N'1. Ugotuj ryż. 2. podsmaż kurczaka na oleju, dodaj cebule, marchew i cukinie. 3. Wymieszaj z ryżem, dopraw solą i pieprzem.', CAST(11.32 AS Decimal(18, 2)), N'Richy', CAST(N'00:00:30' AS Time), CAST(N'0001-01-01T00:00:00.0000000' AS DateTime2), NULL, N'1.Kup produkty. 2.Przy tuj potrawe.', CAST(N'00:00:15' AS Time), 2, CAST(N'00:00:45' AS Time), NULL)
 
INSERT [dbo].[Recipes] ([Id], [Name], [Description], [TotalCost], [AuthorUserName], [CookingTime], [CreatedAt], [ImageUrl], [Instructions], [PreparationTime], [Servings], [TotalTime], [UpdatedAt]) VALUES (61, N'Spaghetti z krewetkami i cytryna', N'1. Ugotuj makaron al dente. 2. podsmaż czosnek i krewetki na oliwie. 3. Dodaj sok z cytryny, wymieszaj z makaronem i podawaj.', CAST(2.84 AS Decimal(18, 2)), N'Richy', CAST(N'00:00:30' AS Time), CAST(N'0001-01-01T00:00:00.0000000' AS DateTime2), NULL, N'1.Kup produkty. 2.Przy tuj potrawe.', CAST(N'00:00:15' AS Time), 2, CAST(N'00:00:45' AS Time), NULL)
 
INSERT [dbo].[Recipes] ([Id], [Name], [Description], [TotalCost], [AuthorUserName], [CookingTime], [CreatedAt], [ImageUrl], [Instructions], [PreparationTime], [Servings], [TotalTime], [UpdatedAt]) VALUES (62, N'Sałatka z papryka i serem feta', N'1. Pokrój papryke i cebule w cienkie paski. 2. Wymieszaj z pokruszonym serem feta i listkami bazylii. 3. Skrop oliwa, dopraw solą i pieprzem. 4. Podawaj schlodzona.', CAST(8.75 AS Decimal(18, 2)), N'Richy', CAST(N'00:00:30' AS Time), CAST(N'0001-01-01T00:00:00.0000000' AS DateTime2), NULL, N'1.Kup produkty. 2.Przy tuj potrawe.', CAST(N'00:00:15' AS Time), 2, CAST(N'00:00:45' AS Time), NULL)
 
INSERT [dbo].[Recipes] ([Id], [Name], [Description], [TotalCost], [AuthorUserName], [CookingTime], [CreatedAt], [ImageUrl], [Instructions], [PreparationTime], [Servings], [TotalTime], [UpdatedAt]) VALUES (63, N'Grillowane warzywa z feta i oregano', N'1. Pokrój warzywa w plastry i grilluj z obu stron. 2. Podawaj z pokruszonym serem feta i posyp świeżym oregano. 3. Skrop oliwa i dopraw solą oraz pieprzem.', CAST(27.22 AS Decimal(18, 2)), N'Richy', CAST(N'00:00:30' AS Time), CAST(N'0001-01-01T00:00:00.0000000' AS DateTime2), NULL, N'1.Kup produkty. 2.Przy tuj potrawe.', CAST(N'00:00:15' AS Time), 2, CAST(N'00:00:45' AS Time), NULL)
 
INSERT [dbo].[Recipes] ([Id], [Name], [Description], [TotalCost], [AuthorUserName], [CookingTime], [CreatedAt], [ImageUrl], [Instructions], [PreparationTime], [Servings], [TotalTime], [UpdatedAt]) VALUES (64, N'Gulasz warzywny z soczewica', N'1. Podsmaż cebule i czosnek na oliwie. 2. Dodaj pokrojona wołowinę i smaż na rumiano. 3. Dodaj przyprawy i dusz przez 1,5  dziny. 4. Podawaj na ciepło.', CAST(29.45 AS Decimal(18, 2)), N'Richy', CAST(N'00:00:30' AS Time), CAST(N'0001-01-01T00:00:00.0000000' AS DateTime2), NULL, N'1.Kup produkty. 2.Przy tuj potrawe.', CAST(N'00:00:15' AS Time), 2, CAST(N'00:00:45' AS Time), NULL)
 
INSERT [dbo].[Recipes] ([Id], [Name], [Description], [TotalCost], [AuthorUserName], [CookingTime], [CreatedAt], [ImageUrl], [Instructions], [PreparationTime], [Servings], [TotalTime], [UpdatedAt]) VALUES (65, N'Kotleciki z soczewicy i warzyw', N'1. Ugotuj soczewice i odcedz. 2. Zmieszaj z przyprawami i mąka, formujac kotleciki. 3. smaż na rozgrzanej patelni po kilka minut z kazdej strony.', CAST(5.01 AS Decimal(18, 2)), N'Richy', CAST(N'00:00:30' AS Time), CAST(N'0001-01-01T00:00:00.0000000' AS DateTime2), NULL, N'1.Kup produkty. 2.Przy tuj potrawe.', CAST(N'00:00:15' AS Time), 2, CAST(N'00:00:45' AS Time), NULL)
 
INSERT [dbo].[Recipes] ([Id], [Name], [Description], [TotalCost], [AuthorUserName], [CookingTime], [CreatedAt], [ImageUrl], [Instructions], [PreparationTime], [Servings], [TotalTime], [UpdatedAt]) VALUES (66, N'Łosoś z cytryna i czosnkiem', N'1. Skrop łososia sokiem z cytryny i dodaj posiekany czosnek. 2. Dopraw solą i pieprzem, piecz w piekarniku przez 20 minut. 3. Podawaj z oliwa i świeżym koperkiem.', CAST(28.34 AS Decimal(18, 2)), N'Richy', CAST(N'00:00:30' AS Time), CAST(N'0001-01-01T00:00:00.0000000' AS DateTime2), NULL, N'1.Kup produkty. 2.Przy tuj potrawe.', CAST(N'00:00:15' AS Time), 2, CAST(N'00:00:45' AS Time), NULL)
 
INSERT [dbo].[Recipes] ([Id], [Name], [Description], [TotalCost], [AuthorUserName], [CookingTime], [CreatedAt], [ImageUrl], [Instructions], [PreparationTime], [Servings], [TotalTime], [UpdatedAt]) VALUES (67, N'Makaron penne z sosem pomidorowym', N'1. Podsmaż cebule i czosnek na oliwie. 2. Dodaj pomidory i  tuj przez 15 minut. 3. Wymieszaj z u towanym makaronem i bazylia. 4. Podawaj na ciepło.', CAST(8.75 AS Decimal(18, 2)), N'Richy', CAST(N'00:00:30' AS Time), CAST(N'0001-01-01T00:00:00.0000000' AS DateTime2), NULL, N'1.Kup produkty. 2.Przy tuj potrawe.', CAST(N'00:00:15' AS Time), 2, CAST(N'00:00:45' AS Time), NULL)
 
INSERT [dbo].[Recipes] ([Id], [Name], [Description], [TotalCost], [AuthorUserName], [CookingTime], [CreatedAt], [ImageUrl], [Instructions], [PreparationTime], [Servings], [TotalTime], [UpdatedAt]) VALUES (68, N'Wołowina duszona z warzywami', N'1. Podsmaż wołowinę na rozgrzanej oliwie. 2. Dodaj cebule i przyprawy, smaż przez kilka minut. 3. Duś przez 1,5  dziny na wolnym ogniu. 4. Podawaj z ryżem lub ziemniakami.', CAST(27.22 AS Decimal(18, 2)), N'Richy', CAST(N'00:00:30' AS Time), CAST(N'0001-01-01T00:00:00.0000000' AS DateTime2), NULL, N'1.Kup produkty. 2.Przy tuj potrawe.', CAST(N'00:00:15' AS Time), 2, CAST(N'00:00:45' AS Time), NULL)
 
INSERT [dbo].[Recipes] ([Id], [Name], [Description], [TotalCost], [AuthorUserName], [CookingTime], [CreatedAt], [ImageUrl], [Instructions], [PreparationTime], [Servings], [TotalTime], [UpdatedAt]) VALUES (69, N'Zupa kalafiorowa z mlekiem kokosowym', N'1. Podsmaż cebule i imbir na oliwie. 2. Dodaj kalafiora i mleko kokosowe,  tuj do miekkosci. 3. Dopraw solą i pieprzem, zmiksuj na krem. 4. Podawaj z grzankami.', CAST(9.86 AS Decimal(18, 2)), N'Richy', CAST(N'00:00:30' AS Time), CAST(N'0001-01-01T00:00:00.0000000' AS DateTime2), NULL, N'1.Kup produkty. 2.Przy tuj potrawe.', CAST(N'00:00:15' AS Time), 2, CAST(N'00:00:45' AS Time), NULL)
 
INSERT [dbo].[Recipes] ([Id], [Name], [Description], [TotalCost], [AuthorUserName], [CookingTime], [CreatedAt], [ImageUrl], [Instructions], [PreparationTime], [Servings], [TotalTime], [UpdatedAt]) VALUES (70, N'Pieczone placki z cukinii i sera feta', N'1. Zetrzyj cukinie na tarce i odcisnij nadmiar wody. 2. Wymieszaj z serem feta, jajkami i mąka. 3. Formuj placki i piecz w piekarniku przez 15 minut.', CAST(9.33 AS Decimal(18, 2)), N'Richy', CAST(N'00:00:30' AS Time), CAST(N'0001-01-01T00:00:00.0000000' AS DateTime2), NULL, N'1.Kup produkty. 2.Przy tuj potrawe.', CAST(N'00:00:15' AS Time), 2, CAST(N'00:00:45' AS Time), NULL)
 
INSERT [dbo].[Recipes] ([Id], [Name], [Description], [TotalCost], [AuthorUserName], [CookingTime], [CreatedAt], [ImageUrl], [Instructions], [PreparationTime], [Servings], [TotalTime], [UpdatedAt]) VALUES (71, N'Kasza jaglana z warzywami i ziolami', N'1. Ugotuj kasze jaglana wedlug instrukcji na opakowaniu. 2. podsmaż cebule, dynie i imbir. 3. Dodaj szpinak i kasze, wymieszaj. 4. Dopraw i podawaj na ciepło.', CAST(8.51 AS Decimal(18, 2)), N'Richy', CAST(N'00:00:30' AS Time), CAST(N'0001-01-01T00:00:00.0000000' AS DateTime2), NULL, N'1.Kup produkty. 2.Przy tuj potrawe.', CAST(N'00:00:15' AS Time), 2, CAST(N'00:00:45' AS Time), NULL)
 
INSERT [dbo].[Recipes] ([Id], [Name], [Description], [TotalCost], [AuthorUserName], [CookingTime], [CreatedAt], [ImageUrl], [Instructions], [PreparationTime], [Servings], [TotalTime], [UpdatedAt]) VALUES (72, N'Zupa krem z papryki i pomidorów', N'1. Upiecz papryke i pomidory w piekarniku. 2. podsmaż cebule i czosnek na oliwie. 3. Dodaj warzywa i bulion,  tuj przez 15 minut. 4. Zmiksuj na krem, dopraw solą i pieprzem, podawaj z bazylia.', CAST(20.64 AS Decimal(18, 2)), N'Richy', CAST(N'00:00:30' AS Time), CAST(N'0001-01-01T00:00:00.0000000' AS DateTime2), NULL, N'1.Kup produkty. 2.Przy tuj potrawe.', CAST(N'00:00:15' AS Time), 2, CAST(N'00:00:45' AS Time), NULL)
 
INSERT [dbo].[Recipes] ([Id], [Name], [Description], [TotalCost], [AuthorUserName], [CookingTime], [CreatedAt], [ImageUrl], [Instructions], [PreparationTime], [Servings], [TotalTime], [UpdatedAt]) VALUES (73, N'Sałatka z grillowane  kurczaka i man ', N'1. Grilluj kurczaka i pokrój w plasterki. 2. Pokrój man  i cebule, wymieszaj z sałatą. 3. Skrop oliwa i sokiem z cytryny, dopraw solą i pieprzem.', CAST(12.23 AS Decimal(18, 2)), N'Richy', CAST(N'00:00:30' AS Time), CAST(N'0001-01-01T00:00:00.0000000' AS DateTime2), NULL, N'1.Kup produkty. 2.Przy tuj potrawe.', CAST(N'00:00:15' AS Time), 2, CAST(N'00:00:45' AS Time), NULL)
 
INSERT [dbo].[Recipes] ([Id], [Name], [Description], [TotalCost], [AuthorUserName], [CookingTime], [CreatedAt], [ImageUrl], [Instructions], [PreparationTime], [Servings], [TotalTime], [UpdatedAt]) VALUES (74, N'Placuszki z twarogu i bananów', N'1. Rozgniec twaróg i banany, wymieszaj z jajkami i mąka. 2. Dodaj cukier i wymieszaj. 3. smaż placuszki na oliwie, az beda zlociste.', CAST(3.88 AS Decimal(18, 2)), N'Richy', CAST(N'00:00:30' AS Time), CAST(N'0001-01-01T00:00:00.0000000' AS DateTime2), NULL, N'1.Kup produkty. 2.Przy tuj potrawe.', CAST(N'00:00:15' AS Time), 2, CAST(N'00:00:45' AS Time), NULL)
 
INSERT [dbo].[Recipes] ([Id], [Name], [Description], [TotalCost], [AuthorUserName], [CookingTime], [CreatedAt], [ImageUrl], [Instructions], [PreparationTime], [Servings], [TotalTime], [UpdatedAt]) VALUES (75, N'Makaron z warzywami i krewetkami', N'1. Ugotuj makaron al dente. 2. Smaż krewetki na oliwie z czosnkiem. 3. Dodaj pokrojona cukinie i papryke, smaż przez kilka minut. 4. Wymieszaj z makaronem i sosem sojowym, dopraw.', CAST(14.61 AS Decimal(18, 2)), N'Richy', CAST(N'00:00:30' AS Time), CAST(N'0001-01-01T00:00:00.0000000' AS DateTime2), NULL, N'1.Kup produkty. 2.Przy tuj potrawe.', CAST(N'00:00:15' AS Time), 2, CAST(N'00:00:45' AS Time), NULL)
 
INSERT [dbo].[Recipes] ([Id], [Name], [Description], [TotalCost], [AuthorUserName], [CookingTime], [CreatedAt], [ImageUrl], [Instructions], [PreparationTime], [Servings], [TotalTime], [UpdatedAt]) VALUES (76, N'Pieczone buraki z serem kozim', N'1. Upiecz buraki w piekarniku. 2. Pokrój buraki i ser kozi, Ułóż na talerzu. 3. Posyp orzechami, skropl miodem i oliwa, dopraw solą i pieprzem.', CAST(4.56 AS Decimal(18, 2)), N'Richy', CAST(N'00:00:30' AS Time), CAST(N'0001-01-01T00:00:00.0000000' AS DateTime2), NULL, N'1.Kup produkty. 2.Przy tuj potrawe.', CAST(N'00:00:15' AS Time), 2, CAST(N'00:00:45' AS Time), NULL)
 
INSERT [dbo].[Recipes] ([Id], [Name], [Description], [TotalCost], [AuthorUserName], [CookingTime], [CreatedAt], [ImageUrl], [Instructions], [PreparationTime], [Servings], [TotalTime], [UpdatedAt]) VALUES (77, N'Gulasz z ciecierzycy i batatów', N'1. Podsmaż cebule i czosnek na oliwie. 2. Dodaj pokrojone bataty, smaż przez kilka minut. 3. Dodaj ciecierzyce, pomidory i przyprawy,  tuj 20 minut. 4. Dodaj szpinak i podawaj.', CAST(13.96 AS Decimal(18, 2)), N'Richy', CAST(N'00:00:30' AS Time), CAST(N'0001-01-01T00:00:00.0000000' AS DateTime2), NULL, N'1.Kup produkty. 2.Przy tuj potrawe.', CAST(N'00:00:15' AS Time), 2, CAST(N'00:00:45' AS Time), NULL)
 
INSERT [dbo].[Recipes] ([Id], [Name], [Description], [TotalCost], [AuthorUserName], [CookingTime], [CreatedAt], [ImageUrl], [Instructions], [PreparationTime], [Servings], [TotalTime], [UpdatedAt]) VALUES (78, N'Tortilla z warzywami i hummusem', N'1. Posmaruj tortille hummusem. 2. Dodaj pokrojone warzywa i salate. 3. Skrop sokiem z cytryny i oliwa, zawin i podawaj.', CAST(5.16 AS Decimal(18, 2)), N'Richy', CAST(N'00:00:30' AS Time), CAST(N'0001-01-01T00:00:00.0000000' AS DateTime2), NULL, N'1.Kup produkty. 2.Przy tuj potrawe.', CAST(N'00:00:15' AS Time), 2, CAST(N'00:00:45' AS Time), NULL)
 
INSERT [dbo].[Recipes] ([Id], [Name], [Description], [TotalCost], [AuthorUserName], [CookingTime], [CreatedAt], [ImageUrl], [Instructions], [PreparationTime], [Servings], [TotalTime], [UpdatedAt]) VALUES (79, N'Zupa krem z marchewki i imbiru', N'1. Podsmaż cebule i imbir na oliwie. 2. Dodaj pokrojona marchew i bulion,  tuj do miekkosci. 3. Zmiksuj na krem, dopraw solą i pieprzem.', CAST(11.66 AS Decimal(18, 2)), N'Richy', CAST(N'00:00:30' AS Time), CAST(N'0001-01-01T00:00:00.0000000' AS DateTime2), NULL, N'1.Kup produkty. 2.Przy tuj potrawe.', CAST(N'00:00:15' AS Time), 2, CAST(N'00:00:45' AS Time), NULL)
 
INSERT [dbo].[Recipes] ([Id], [Name], [Description], [TotalCost], [AuthorUserName], [CookingTime], [CreatedAt], [ImageUrl], [Instructions], [PreparationTime], [Servings], [TotalTime], [UpdatedAt]) VALUES (80, N'Pieczony kurczak z cytryna i rozmarynem', N'1. Natrzyj kurczaka oliwa, czosnkiem, solą i pieprzem. 2. Dodaj cytryne pokrojona w plasterki i rozmaryn. 3. Piecz w piekarniku przez 1,5  dziny w 180°C.', CAST(24.79 AS Decimal(18, 2)), N'Richy', CAST(N'00:00:30' AS Time), CAST(N'0001-01-01T00:00:00.0000000' AS DateTime2), NULL, N'1.Kup produkty. 2.Przy tuj potrawe.', CAST(N'00:00:15' AS Time), 2, CAST(N'00:00:45' AS Time), NULL)
 
INSERT [dbo].[Recipes] ([Id], [Name], [Description], [TotalCost], [AuthorUserName], [CookingTime], [CreatedAt], [ImageUrl], [Instructions], [PreparationTime], [Servings], [TotalTime], [UpdatedAt]) VALUES (81, N'Sałatka z rukola, truskawkami i serem pleśniowym', N'1. Pokrój truskawki i ser pleśniowy. 2. Wymieszaj z rukola i posyp orzechami. 3. Skrop miodem i oliwa, dopraw solą i pieprzem.', CAST(6.99 AS Decimal(18, 2)), N'Richy', CAST(N'00:00:30' AS Time), CAST(N'0001-01-01T00:00:00.0000000' AS DateTime2), NULL, N'1.Kup produkty. 2.Przy tuj potrawe.', CAST(N'00:00:15' AS Time), 2, CAST(N'00:00:45' AS Time), NULL)
 
INSERT [dbo].[Recipes] ([Id], [Name], [Description], [TotalCost], [AuthorUserName], [CookingTime], [CreatedAt], [ImageUrl], [Instructions], [PreparationTime], [Servings], [TotalTime], [UpdatedAt]) VALUES (82, N'Pizza Capriciosa', N'1. Przy tuj ciasto na pizzę i rozwałkuj na okrągły placek. 2. Posmaruj sosem pomidorowym. 3. Dodaj startą mozzarellę, pokrojoną szynkę i pieczarki. 4. Skrop oliwą i posyp oregano oraz bazylią. 5. Piecz w temperaturze 220°C przez 12-15 minut.', CAST(12.04 AS Decimal(18, 2)), N'Richy', CAST(N'00:00:30' AS Time), CAST(N'0001-01-01T00:00:00.0000000' AS DateTime2), NULL, N'1.Kup produkty. 2.Przy tuj potrawe.', CAST(N'00:00:15' AS Time), 2, CAST(N'00:00:45' AS Time), NULL)
 
INSERT [dbo].[Recipes] ([Id], [Name], [Description], [TotalCost], [AuthorUserName], [CookingTime], [CreatedAt], [ImageUrl], [Instructions], [PreparationTime], [Servings], [TotalTime], [UpdatedAt]) VALUES (83, N'Spaghetti Carbonara', N'1. Ugotuj spaghetti al dente. 2. Podsmaż boczek z drobno posiekanym czosnkiem. 3. Wymieszaj jajka z startym parmezanem, pieprzem i solą. 4. Połącz u towane spaghetti z boczkiem, zdejmij z ognia i dodaj masę jajeczną. 5. Szybko wymieszaj, aby uzyskać kremowy sos.', CAST(11.78 AS Decimal(18, 2)), N'Richy', CAST(N'00:00:30' AS Time), CAST(N'0001-01-01T00:00:00.0000000' AS DateTime2), NULL, N'1.Kup produkty. 2.Przy tuj potrawe.', CAST(N'00:00:15' AS Time), 2, CAST(N'00:00:45' AS Time), NULL)
 
INSERT [dbo].[Recipes] ([Id], [Name], [Description], [TotalCost], [AuthorUserName], [CookingTime], [CreatedAt], [ImageUrl], [Instructions], [PreparationTime], [Servings], [TotalTime], [UpdatedAt]) VALUES (84, N'Spaghetti Bolognese', N'1. Podsmaż posiekaną cebulę i czosnek na oliwie. 2. Dodaj mięso mielone i smaż, aż się zarumieni. 3. Wlej sos pomidorowy i dopraw bazylią, solą i pieprzem. 4. Duś przez 15 minut na małym ogniu. 5. Ugotuj spaghetti i wymieszaj z sosem.', CAST(17.07 AS Decimal(18, 2)), N'Richy', CAST(N'00:00:30' AS Time), CAST(N'0001-01-01T00:00:00.0000000' AS DateTime2), NULL, N'1.Kup produkty. 2.Przy tuj potrawe.', CAST(N'00:00:15' AS Time), 2, CAST(N'00:00:45' AS Time), NULL)
 
INSERT [dbo].[Recipes] ([Id], [Name], [Description], [TotalCost], [AuthorUserName], [CookingTime], [CreatedAt], [ImageUrl], [Instructions], [PreparationTime], [Servings], [TotalTime], [UpdatedAt]) VALUES (85, N'Spaghetti Napoli', N'1. Podsmaż czosnek na oliwie, aż lekko się zarumieni. 2. Dodaj sos pomidorowy i przyprawy. 3. Duś na małym ogniu przez 10 minut. 4. Ugotuj spaghetti al dente. 5. Wymieszaj makaron z sosem i udekoruj bazylią.', CAST(5.25 AS Decimal(18, 2)), N'Richy', CAST(N'00:00:30' AS Time), CAST(N'0001-01-01T00:00:00.0000000' AS DateTime2), NULL, N'1.Kup produkty. 2.Przy tuj potrawe.', CAST(N'00:00:15' AS Time), 2, CAST(N'00:00:45' AS Time), NULL)
 
INSERT [dbo].[Recipes] ([Id], [Name], [Description], [TotalCost], [AuthorUserName], [CookingTime], [CreatedAt], [ImageUrl], [Instructions], [PreparationTime], [Servings], [TotalTime], [UpdatedAt]) VALUES (86, N'Burrito', N'1. Podsmaż kurczaka z przyprawą meksykańską. 2. Ugotuj ryż i wymieszaj z fasolą oraz salsą. 3. Dodaj pokrojoną paprykę i cebulę. 4. Na tortillach umieść farsz, posyp serem i zawiń. 5. Podpiecz burrito w piekarniku przez 5 minut.', CAST(6.62 AS Decimal(18, 2)), N'Richy', CAST(N'00:00:30' AS Time), CAST(N'0001-01-01T00:00:00.0000000' AS DateTime2), NULL, N'1.Kup produkty. 2.Przy tuj potrawe.', CAST(N'00:00:15' AS Time), 2, CAST(N'00:00:45' AS Time), NULL)
 
INSERT [dbo].[Recipes] ([Id], [Name], [Description], [TotalCost], [AuthorUserName], [CookingTime], [CreatedAt], [ImageUrl], [Instructions], [PreparationTime], [Servings], [TotalTime], [UpdatedAt]) VALUES (87, N'Pad Thai', N'1. Ugotuj makaron ryżowy według instrukcji. 2. Podsmaż kurczaka, dodaj rozbełtane jajko i wymieszaj. 3. Dodaj makaron, sosy, cukier i sok z limonki. 4. Smaż na dużym ogniu przez 3 minuty. 5. Posyp posiekanym szczypiorkiem i orzechami.', CAST(22.59 AS Decimal(18, 2)), N'Richy', CAST(N'00:00:30' AS Time), CAST(N'0001-01-01T00:00:00.0000000' AS DateTime2), NULL, N'1.Kup produkty. 2.Przy tuj potrawe.', CAST(N'00:00:15' AS Time), 2, CAST(N'00:00:45' AS Time), NULL)
 
SET IDENTITY_INSERT [dbo].[Recipes] OFF
 





