SET PriceForSingle = 0.20
WHERE Id = 9;

UPDATE Ingredients
SET PriceForSingle = 0.20
WHERE Id = 8;


UPDATE r
SET TotalCost = (
    SELECT SUM(
        CASE
            WHEN ri.IngredientId IN (3, 9) AND i.PriceForSingle IS NOT NULL
            THEN i.PriceForSingle * ri.Quantity
            ELSE i.PriceFor100Grams * (ri.Quantity / 100.0)
        END
    )
    FROM RecipeIngredients AS ri
    JOIN Ingredients AS i ON ri.IngredientId = i.Id
    WHERE ri.RecipeId = r.Id
)
FROM Recipes AS r;




